function priorities() { const night = daylight(T) < 0.3, h = hourOf(T), toDark = (SZ.sunset - h + 24) % 24, list = [], here = LOOK ? LOOK.kind : "", W = SEASON === "winter", Su = SEASON === "summer";
  const shelter = Su ? ["Make a sleeping spot", `Nights are warm (about ${Math.round(SZ.lo)} °C), so shelter is about rain and bugs. 1) Pick a spot on a gentle rise, away from the creek (mosquitoes, flash floods) and not under a dead tree. 2) Lean a row of branches against a log or a branch wedged between two trees, about waist high, and lay leafy boughs on it for shade and rain. 3) Rake up a bed of leaves about 15 cm (6 in) thick: it keeps you off the damp ground and away from ticks.`]
    : ["Build a debris hut", `Tonight it drops to about ${Math.round(SZ.lo)} °C${W ? " (hard frost)" : ""}. A debris hut keeps you alive with no fire. ${here === "log" ? "This log will do as one side. " : ""}1) Find a ridgepole about 3 m (10 ft) long, as thick as your wrist, and rest one end on a stump, a log or the fork of a tree at hip height, the other on the ground. 2) Lean sticks against both sides of it every hand's width, leaving inside just enough room to lie down: the smaller it is, the warmer. 3) Pile leaves on top at least an arm's length (60-90 cm) thick: the thickness is what keeps you warm, and it sheds rain. 4) Fill the inside with dry leaves and lie on a bed of them at least 30 cm (1 ft) thick: the cold ground pulls heat out of you much faster than the air does. 5) Crawl in feet first and pull a pile of leaves into the doorway. It takes 2-3 hours, so start by about ${Math.round(SZ.sunset - 3) - 12} pm.`];
  const water = !FOUND.creek ? ["Find water", "1) Walk downhill: water collects in the valleys. 2) Follow a dry gully down; it leads to a creek. 3) Look for big white-barked sycamores; they grow along creeks and you can see them from a ridge. 4) Stop and listen for running water. You need about 2-3 litres a day, more in heat."]
    : ["Make the water safe", `${FOUND.can ? "You have a can: " : "If you find a metal can: "}1) Fill it at the fastest, clearest riffle. 2) Set it on the coals of a fire, or against the flames, until it bubbles hard, and keep it there a minute. 3) Let it cool and drink. A clear plastic bottle left in full sun for 6 hours also works. With no way to treat it, drink it anyway: Giardia takes 1-3 weeks to make you sick, dehydration can kill in 3 days. Digging a hole in the sand a metre from the creek gives clearer water (it filters dirt, not germs).`];
  const fire = ["Make a fire", `With no matches, a bow drill works: 1) Bow: a curved stick about arm's length, with a shoelace tied end to end. 2) Spindle: a straight, dry, dead stick about 20 cm long and thumb thick (red cedar, willow, sycamore or cottonwood), pointed at the top, blunt at the bottom. 3) Fireboard: a flat piece of the same dry wood; cut a notch at its edge. 4) Socket: a stone or a knot of hard wood to press on top. 5) Twist the spindle into the bowstring, kneel on the board, and saw the bow fast and steady until black dust smokes in the notch; that dust becomes a glowing coal. 6) Drop the coal into a tinder bundle (shredded cedar inner bark, hickory shag, dry grass) and blow gently until it flames. Before you start, gather fuel: a big handful of pencil-thin dead twigs, then thumb-thick, then wrist-thick, from dead branches still on trees (wood on the ground is damp). ${W ? "In winter, fire is close to essential." : ""}`];
  const signal = ["Make yourself easy to find", "Searchers start where you were last seen, so set up camp nearby, next to an opening. 1) In the clearest spot, lay out a big X or SOS of logs, branches or rocks, each line 3 m (10 ft) long, dark on light ground (or stamp it in snow). 2) By day, put green leaves on your fire for white smoke. 3) Hang anything brightly coloured where it shows. 4) Signal in threes: three shouts, three whistles, three knocks on a tree. Then stay put."];
  const food = ["Find food", W ? "Food can wait three weeks, but in cold it keeps you warm. In January: 1) Hickory nuts and acorns lie under the snow and leaves under the trees; crack hickory nuts with a rock. 2) Acorns (white oak are best): shell, crush, then boil in changes of water, or soak in the creek in a bundle, until they aren't bitter. 3) Wild onion and garlic mustard stay green in winter. 4) Rose hips on wild rose bushes. Don't eat mushrooms or anything you can't name for certain."
    : Su ? "Food can wait three weeks. In July: 1) Blackberries and black raspberries along field edges. 2) Crayfish under rocks in the creek: boil them (never raw). 3) Cattail shoots: peel and eat the white core. 4) Sumac berries make a lemony drink in cold water. Don't eat mushrooms or anything you can't name for certain."
    : "Food can wait three weeks. In late October: 1) Hickory nuts: under shagbark hickories, crack with a rock. 2) Black walnuts: crush the husks off, crack hard. 3) Persimmons: soft orange fruit, sweet after frost (unripe ones pucker your mouth). 4) Acorns: white oak are best; shell, crush, boil in changes of water until not bitter, then roast. 5) The last pawpaws in creek bottoms. Don't eat mushrooms or anything you can't name for certain."];
  if (!Su && (toDark < 5 || night)) list.push(shelter);
  if (Su && h > 11 && h < 17) list.push(["Beat the heat", "1) Rest in deep shade through the afternoon; move in the morning and evening. 2) Soak your shirt in the creek and put it back on: evaporation cools you. 3) Check for ticks morning and night (lone star and deer ticks): look along your waistband, behind your knees, in your hair. 4) Avoid poison ivy: three leaflets, and hairy vines on trees."]);
  if (!FOUND.creek || BODY.water > 1.2) list.push(water);
  if (!list.includes(shelter)) list.push(shelter);
  list.push(fire); if (FOUND.creek && !list.includes(water)) list.push(water); list.push(signal); list.push(food);
  return list; }

